func TestPodmanHelper(t *testing.T) {
	state := os.Getenv("TS_761_PODMAN_STATE")
	if state == "" {
		return
	}
	var args []string
	for i, arg := range os.Args {
		if arg == "--" {
			args = os.Args[i+1:]
			break
		}
	}
	if len(args) == 0 {
		os.Exit(2)
	}
	name := args[len(args)-1]
	switch args[0] {
	case "run":
		label := ""
		for i, arg := range args {
			if arg == "--name" {
				name = args[i+1]
			}
			if arg == "--label" {
				label = strings.TrimPrefix(args[i+1], "ts-bench-job=")
			}
		}
		f, err := os.Open("/proc/self/fd/3")
		if err != nil {
			os.Exit(2)
		}
		env, err := io.ReadAll(f)
		f.Close()
		if err != nil || !bytes.Contains(env, []byte("TS_BENCH_CLIENT_SECRET=private-test-value")) {
			os.Exit(2)
		}
		if err := os.WriteFile(filepath.Join(state, name), []byte(label), 0600); err != nil {
			os.Exit(2)
		}
		switch os.Getenv("TS_761_PODMAN_MODE") {
		case "warmup":
			var w Workload
			if json.NewDecoder(os.Stdin).Decode(&w) != nil {
				os.Exit(2)
			}
			client, delay := "go", 10
			if strings.HasSuffix(name, "-rust") {
				client, delay = "rust", 6
			}
			at := time.Now().UTC().Add(-time.Duration(w.Warmup+w.Duration+delay) * time.Second)
			encoder := json.NewEncoder(os.Stdout)
			for second := range w.Warmup + w.Duration {
				count, p99 := uint64(100), 100.0
				if second < w.Warmup {
					count, p99 = 10, w.Targets.P99*1500
				}
				_ = encoder.Encode(Sample{TS: at.Add(time.Duration(second) * time.Second), Client: client, SDK: client, SDKVersion: "test", Region: "gru", Op: "doc.get", Count: count, P50: 10, P95: 30, P99: p99, Max: p99})
			}
			_ = encoder.Encode(Sample{Type: "summary", Client: client, Region: "gru", Workload: w.Name, OpsPerS: 100, PerOp: map[string]json.RawMessage{"doc.get": json.RawMessage(`{}`)}})
			os.Exit(0)
		case "oversized":
			_, _ = io.WriteString(os.Stdout, strings.Repeat("x", 1<<20))
			for {
				time.Sleep(time.Minute)
			}
		case "stream":
			_ = json.NewEncoder(os.Stdout).Encode(Sample{TS: time.Now().UTC(), Client: "go", SDK: "go", SDKVersion: "test", Region: "gru", Op: "doc.get", Count: 100, P99: 30, Max: 40})
			for {
				time.Sleep(time.Minute)
			}
		case "missing-fields":
			_ = json.NewEncoder(os.Stdout).Encode(map[string]any{"ts": time.Now().UTC(), "client": "go", "sdk": "go", "sdk_version": "test", "region": "gru", "op": "doc.get", "count": 100, "errors": 0})
			for {
				time.Sleep(time.Minute)
			}
		}
