// sampleLaunch has exactly the members `oci-region preview seed-launch`
// writes (internal/ociregion/seed.go seedLaunch).
const sampleLaunch = `{"availabilityDomain":"AD-1","faultDomain":"FAULT-DOMAIN-1","compartmentId":"ocid1.compartment.oc1..c","displayName":"gru-1-ctl-1","shape":"VM.Standard.A1.Flex","shapeConfig":{"ocpus":1,"memoryInGBs":6},"sourceDetails":{"sourceType":"image","imageId":"ocid1.image.fixture","bootVolumeSizeInGBs":50,"bootVolumeVpusPerGB":10},"subnetId":"ocid1.subnet.oc1..s","privateIp":"10.0.0.11","nsgIds":["ocid1.networksecuritygroup.oc1..n"],"assignPublicIp":false,"metadata":{"terrascale-bootstrap":"{\"schemaVersion\":1,\"slot\":\"controller-a\"}","user_data":"Y2xvdWQtaW5pdA=="},"freeformTags":{"BootstrapCreateKey":"seed-a"}}`

type policyCloud struct {
	Cloud
	statements []string
	etag       string
	updated    [][]string
	matched    []string
	objects    map[string][]byte
	reads      int
}

func (p *policyCloud) PolicyStatements(context.Context, string) ([]string, string, error) {
	return p.statements, p.etag, nil
}
func (p *policyCloud) ReplacePolicyStatements(_ context.Context, _ string, etag string, statements []string) error {
	p.updated, p.matched = append(p.updated, statements), append(p.matched, etag)
	return nil
}

// conveniences that the API carries in createVnicDetails.
type seedLaunch struct {
	AvailabilityDomain string `json:"availabilityDomain"`
	FaultDomain        string `json:"faultDomain"`
	CompartmentID      string `json:"compartmentId"`
	DisplayName        string `json:"displayName"`
	Shape              string `json:"shape"`
	ShapeConfig        struct {
		OCPUs       float32 `json:"ocpus"`
		MemoryInGBs float32 `json:"memoryInGBs"`
	} `json:"shapeConfig"`
	SourceDetails struct {
		SourceType          string `json:"sourceType"`
		ImageID             string `json:"imageId"`
		BootVolumeSizeInGBs int64  `json:"bootVolumeSizeInGBs"`
		BootVolumeVpusPerGB int64  `json:"bootVolumeVpusPerGB"`
	} `json:"sourceDetails"`
	SubnetID       string            `json:"subnetId"`
	PrivateIP      string            `json:"privateIp"`
	NSGIDs         []string          `json:"nsgIds"`
	AssignPublicIP *bool             `json:"assignPublicIp"`
	Metadata       map[string]string `json:"metadata"`
	FreeformTags   map[string]string `json:"freeformTags"`
}

// LaunchDetails decodes a controller launch input into the SDK launch
// request. Every member must be known and present: an unknown member would
// otherwise be dropped silently from the launch.
func LaunchDetails(wire []byte) (core.LaunchInstanceDetails, error) {
	var input seedLaunch
	if err := json.Unmarshal(wire, &input, json.RejectUnknownMembers(true)); err != nil {
		return core.LaunchInstanceDetails{}, fmt.Errorf("decode controller launch input: %w", err)
	}
	source := input.SourceDetails
	if input.AvailabilityDomain == "" || input.FaultDomain == "" || input.CompartmentID == "" || input.DisplayName == "" ||
		input.Shape == "" || input.ShapeConfig.OCPUs <= 0 || input.ShapeConfig.MemoryInGBs <= 0 ||
		source.SourceType != "image" || source.ImageID == "" || source.BootVolumeSizeInGBs <= 0 || source.BootVolumeVpusPerGB <= 0 ||
		input.SubnetID == "" || input.PrivateIP == "" || len(input.NSGIDs) == 0 || input.AssignPublicIP == nil ||
		len(input.Metadata) == 0 || len(input.FreeformTags) == 0 {
		return core.LaunchInstanceDetails{}, errors.New("controller launch input lacks a required member")
	}
	return core.LaunchInstanceDetails{
		AvailabilityDomain: &input.AvailabilityDomain, FaultDomain: &input.FaultDomain, CompartmentId: &input.CompartmentID,
		DisplayName: &input.DisplayName, Shape: &input.Shape,
		ShapeConfig: &core.LaunchInstanceShapeConfigDetails{Ocpus: &input.ShapeConfig.OCPUs, MemoryInGBs: &input.ShapeConfig.MemoryInGBs},
		SourceDetails: core.InstanceSourceViaImageDetails{ImageId: &source.ImageID,
			BootVolumeSizeInGBs: &source.BootVolumeSizeInGBs, BootVolumeVpusPerGB: &source.BootVolumeVpusPerGB},
		CreateVnicDetails: &core.CreateVnicDetails{SubnetId: &input.SubnetID, PrivateIp: &input.PrivateIP,
			NsgIds: input.NSGIDs, AssignPublicIp: input.AssignPublicIP},
		Metadata: input.Metadata, FreeformTags: input.FreeformTags,
	}, nil
}

// LaunchRetryToken binds an OCI retry token to the exact launch input bytes.
func LaunchRetryToken(wire []byte) string {
	return entityid.Derive("attempt-launch", string(wire))
}

func (a *Attempt) cloud(operation string) Cloud {
	if a.err != nil {
		return nil
	}
	if a.Cloud == nil {
		cloud, err := newSDKCloud(a.Cell().OCIRegion)
		if err != nil {
			a.fail(err)
			return nil
		}
		a.Cloud = cloud
	}
	fmt.Fprintf(a.Out, "%s OCI %s ...\n", a.Now().UTC().Format("15:04:05"), operation)
	return a.Cloud
}

// typed re-decodes value into the struct a signing command decodes, so the

func (a *Attempt) controllerObjectGrants(plan Object) {
	ids := object(plan["resource_ids"])
	expected, e := ociregion.RequiredControllerStatements(plan, ids, a.Prefix)
	a.fail(e)
	if a.err != nil {
		return
	}
	cloud := a.cloud("GetPolicy")
	if cloud == nil {
		return
	}
	policyID := str(ids, "controller_policy")
	statements, etag, e := cloud.PolicyStatements(a.ctx, policyID)
	a.fail(e)
	if a.err != nil || slices.Equal(statements, expected) {
		return
	}
	// The replacement is conditional on the version just read; without an
	// ETag it would silently overwrite a concurrent policy change.
	if etag == "" {
		a.fail(fmt.Errorf("OCI policy %s read returned no ETag; refusing an unconditional update", policyID))
		return
	}
	if cloud = a.cloud("UpdatePolicy"); cloud != nil {
		a.fail(cloud.ReplacePolicyStatements(a.ctx, policyID, etag, expected))
	}
	if a.err == nil {
		fmt.Fprintln(a.Out, "controller object grants now target prefix", a.Prefix, "- waiting for IAM propagation")
		a.fail(a.Sleep(a.ctx, time.Minute))
	}
}

func slotRecordPrefixes(prefix, deployment string) []string {
	return []string{prefix + "/bootstrap/v1/" + deployment + "/", prefix + "/bootstrap/v2/" + deployment + "/"}
}

func SeedLaunchDocument(reviewed, host Object, name string, metadata Object) Object {
	return Object{"availabilityDomain": reviewed["availability_domain"], "faultDomain": reviewed["fault_domain"], "compartmentId": reviewed["compartment_id"], "displayName": name, "shape": reviewed["shape"], "shapeConfig": Object{"ocpus": reviewed["ocpus"], "memoryInGBs": reviewed["memory_gb"]}, "sourceDetails": Object{"sourceType": "image", "imageId": reviewed["image_id"], "bootVolumeSizeInGBs": reviewed["boot_gb"], "bootVolumeVpusPerGB": reviewed["boot_vpus_per_gb"]}, "subnetId": reviewed["subnet_id"], "privateIp": host["private_ip"], "nsgIds": reviewed["network_security_group_ids"], "assignPublicIp": reviewed["assign_public_ip"], "metadata": metadata, "freeformTags": Object{"BootstrapCreateKey": reviewed["create_identity"]}}
}

func memberTags(plan Object, name string) Object {
	return Object{"terrascale-owner": plan["orchestrator_owner"], "terrascale-resource": "terrabase-host", "terrascale-host-node": name}
}

// MemberLaunchDocument is the C# database host launch input `preview
// member-launch` writes. It has SeedLaunchDocument's shape, so
// internal/attempt decodes it with the same strict reader.
func MemberLaunchDocument(plan, host Object, name, imageID string, metadata Object) Object {
	ids := obj(plan["resource_ids"])
	reviewed := Object{"availability_domain": plan["availability_domain"], "fault_domain": host["fault_domain"], "compartment_id": ids["workload_compartment"], "shape": host["shape"], "ocpus": host["ocpus"], "memory_gb": host["memory_gb"], "image_id": imageID, "boot_gb": host["boot_gb"], "boot_vpus_per_gb": plan["volume_vpus_per_gb"], "subnet_id": ids["subnet"], "network_security_group_ids": []any{ids["workload_network_security_group"]}, "assign_public_ip": false}
	document := SeedLaunchDocument(reviewed, host, name, metadata)
	document["freeformTags"] = memberTags(plan, name)
	return document
}

func storageStatements(plan, ids Object, prefix string, ledgerKey ...string) []string {
	identity, names, buckets := obj(plan["identity"]), obj(plan["preview_compartment_names"]), obj(plan["foundation_buckets"])
	dg, control := str(identity["controller_dynamic_group_name"]), str(names["control"])
	prefix = canonicalPrefix(prefix)
	r := []string{fmt.Sprintf("Allow dynamic-group %s to read objectstorage-namespaces in tenancy", dg)}
	for _, role := range []string{"ledger", "head", "backup", "material"} {
		r = append(r, fmt.Sprintf("Allow dynamic-group %s to read buckets in compartment %s where target.bucket.name='%s'", dg, control, str(buckets[role])))
	}
	for _, role := range []string{"ledger", "head"} {
		permissions := "request.permission='OBJECT_CREATE'"
		if role == "head" {
			permissions += ", request.permission='OBJECT_OVERWRITE'"
		}
		for _, version := range []string{"v1", "v2"} {
			name := "bootstrap/" + version + "/*"
			reserved := "bootstrap/v2/material-source/*"
			if prefix != "" {
				name = prefix + "/" + name
				reserved = prefix + "/" + reserved
			}
			exclusion := ""
			if version == "v2" {
				exclusion = fmt.Sprintf("target.object.name != /%s/, ", reserved)
			}
			r = append(r,
				fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name=/%s/, request.permission='OBJECT_READ'}", dg, control, str(buckets[role]), name),
				fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name=/%s/, %sany {%s}}", dg, control, str(buckets[role]), name, exclusion, permissions))
		}
	}
	// The leader keeps the configuration KV buckets in the versioned head
	// bucket (controller.kv_snapshot, docs/storage.md).
	r = append(r, fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name='kv-snapshot/v1/*', any {request.permission='OBJECT_READ', request.permission='OBJECT_CREATE', request.permission='OBJECT_OVERWRITE'}}", dg, control, str(buckets["head"])))
	// The leader follows the region's orchestrator release channel, which CI
	// writes, and reports its progress there (docs/continuous-delivery.md).
	r = append(r, fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name='releases/*', request.permission='OBJECT_READ'}", dg, control, str(buckets["head"])),
		fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name='releases/orchestrator/status.json', any {request.permission='OBJECT_CREATE', request.permission='OBJECT_OVERWRITE'}}", dg, control, str(buckets["head"])))
	// ... and each service release channel's report (TS-610), one statement
	// per role of internal/app's serviceReleaseRoles: OCI matches a * only
	// at the end of an object name, so services/*/status.json grants nothing.
	for _, role := range []string{"terrabase", "ts-auth"} {
		r = append(r, fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name='releases/services/%s/status.json', any {request.permission='OBJECT_CREATE', request.permission='OBJECT_OVERWRITE'}}", dg, control, str(buckets["head"]), role))
	}
	r = append(r, fmt.Sprintf("Allow dynamic-group %s to manage objects in compartment %s where all {target.bucket.name='%s', target.object.name='material/v2/*', any {request.permission='OBJECT_READ', request.permission='OBJECT_CREATE'}}", dg, control, str(buckets["material"])))
	keys := []string{str(ids["key"])}
	if len(ledgerKey) > 0 && ledgerKey[0] != keys[0] {
		keys = append(keys, ledgerKey[0])
	}
	for _, key := range keys {
		r = append(r, fmt.Sprintf("Allow dynamic-group %s to use keys in compartment %s where all {target.key.id='%s', any {request.permission='KEY_ENCRYPT', request.permission='KEY_DECRYPT'}}", dg, control, key), fmt.Sprintf("Allow dynamic-group %s to use key-delegate in compartment %s where target.key.id='%s'", dg, control, key))
	}
	return r
}
func controllerStatements(plan, ids Object, prefix string, ledgerKey ...string) []string {
	dg := str(obj(plan["identity"])["controller_dynamic_group_name"])
	names := obj(plan["preview_compartment_names"])
	r := []string{}
	for _, row := range [][3]string{{"manage", "instance-family", "control"}, {"manage", "instance-family", "workload"}, {"read", "instance-images", "control"}, {"use", "virtual-network-family", "network"}, {"use", "load-balancers", "network"}, {"manage", "volume-family", "control"}, {"manage", "volume-family", "workload"}} {
		r = append(r, fmt.Sprintf("Allow dynamic-group %s to %s %s in compartment %s", dg, row[0], row[1], str(names[row[2]])))
	}
	r = append(r, fmt.Sprintf("Allow dynamic-group %s to read secret-bundles in compartment %s where target.secret.name != /ts-bootstrap-source-*/", dg, str(names["control"])))
	return append(r, storageStatements(plan, ids, prefix, ledgerKey...)...)
}
func RequiredControllerStatements(plan, ids Object, prefix string) ([]string, error) {
	return capture(func() []string { return controllerStatements(plan, ids, prefix) })
}

func capture[T any](fn func() T) (v T, err error) {
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(error); ok {
				err = e
			} else {
				err = fmt.Errorf("%v", r)
			}
		}
	}()
	return fn(), nil
}

// New returns a cryptographically random ULID, monotonic within a millisecond.
func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

// Derive gives an idempotent operation a stable ULID. A zero timestamp marks
// derived identities as having no creation time; the 80 entropy bits bind the
// domain-separated input. New entities use New instead.
func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}

