const fakeVault = "ocid1.vault.oc1..fake"

// fakeLeader answers the services phase's operator commands as the
// authority leader would: a change the applied spec already holds plans
// nothing and writes no candidate.
type fakeLeader struct {
	applied  map[string]bool
	planned  map[string]string // candidate or signed file -> change
	commands [][]string
}

func (l *fakeLeader) run(_ context.Context, c Command) (string, error) {
	l.commands = append(l.commands, c.Args)
	out := flagValue(c.Args, "--out")
	var change string
	switch {
	case slices.Contains(c.Args, "rm"):
		for _, path := range c.Args[slices.Index(c.Args, "--")+1:] {
			os.Remove(path)
		}
		return "", nil
	case slices.Contains(c.Args, "sign-spec-delegation"):
		return "", os.WriteFile(out, []byte("{}"), 0o600)
	case slices.Contains(c.Args, "sign-spec"):
		l.planned[out] = l.planned[flagValue(c.Args, "--candidate")]
		return "", os.WriteFile(out, []byte("{}"), 0o600)
	case slices.Contains(c.Args, "apply"):
		l.applied[l.planned[flagValue(c.Args, "--file")]] = true
		return "", nil
	case slices.Contains(c.Args, "add"):
		change = "service " + flagValue(c.Args, "--role") + " " + flagValue(c.Args, "--profile")
	case slices.Contains(c.Args, "grant-host"):
		change = "grant " + strings.Join(c.Args[slices.Index(c.Args, "--node"):], " ")
	default:
		return "", nil
	}
	if l.applied[change] {
		return `{"status":"unchanged"}`, nil
	}
	l.planned[out] = change
	return `{"status":"planned","root_required":["` + change + `"]}`, os.WriteFile(out, []byte("{}"), 0o600)
}

// count is how many commands contain word.
func (l *fakeLeader) count(word string) int {
	return len(slices.DeleteFunc(slices.Clone(l.commands), func(c []string) bool { return !slices.Contains(c, word) }))
}

// servicesAttempt is an attempt over plan, bound to a fake Vault, with
// memberCA as its material's TerraBase member CA.
func servicesAttempt(t *testing.T, plan, memberCA string) (*Attempt, *fakeLeader) {
	t.Helper()
	a := smallAttempt(t)
	a.Config["trust"] = Object{"root_public": "/keys/root.pub", "root_private": "/keys/root.key",
		"release_leaf_public": "/keys/leaf.pub", "release_leaf_private": "/keys/leaf.key"}
	bound := a.read(plan)
	object(bound["resource_ids"])["vault"] = fakeVault
	a.writeJSON(a.Plan(), bound)
	a.fail(a.WriteNew(a.Path("material", "terrabase-member-ca.pem"), []byte(memberCA)))
	if a.Err() != nil {
		t.Fatal(a.Err())
	}
	leader := &fakeLeader{applied: map[string]bool{}, planned: map[string]string{}}
	a.Runner = leader.run
	return a, leader
}

const testCA = "-----BEGIN CERTIFICATE-----\nfixture\n-----END CERTIFICATE-----\n"

// The ports every cell's TerraBase members listen on; the plans' NSG rules
// admit them.
const terraBasePeerPort, terraBaseClientPort = 9443, 9465

// apiURL and authOrigin are a cell's regional TerraBase API and ts-auth
// origins, sfo.api.terrascale.tech and sfo.auth.terrascale.tech.
func apiURL(cell catalog.Entry) string { return "https://" + cell.Name() + ".api.terrascale.tech" }
func authOrigin(cell catalog.Entry) string {
	return "https://" + cell.Name() + ".auth.terrascale.tech"
}

// derivedProfile is where the services phase writes the profile of role it
// derives from the plan.
func (a *Attempt) derivedProfile(role string) string { return a.Path("services", role+".profile.json") }

// terraBaseProfile is the TerraBase profile the cell runs: terrabase_profile,
// or the one the services phase derived.
func (a *Attempt) terraBaseProfile() string {
	if path := str(a.Config, "terrabase_profile"); path != "" {
		return path
	}
	if path := a.derivedProfile(terrabase.Role); exists(path) {
		return path
	}
	return ""
}

type node struct{ name, ip string }

// terraBaseMembers are the plan's TerraBase members in placement order, the
// first the catalog primary: its database hosts, or in a colocated cell,
// which has none, its controllers.
func terraBaseMembers(cell catalog.Entry, plan Object) ([]node, error) {
	var members, controllers []node
	for _, v := range rows(plan["hosts"]) {
		host := object(v)
		slot := str(host, "slot")
		var name string
		var err error
		switch {
		case strings.HasPrefix(slot, "member-"):
			name, err = naming.RegionCell(cell.Cell).MemberSlot(slot)
			members = append(members, node{name, str(host, "private_ip")})
		case strings.HasPrefix(slot, "controller-"):
			name, err = naming.RegionCell(cell.Cell).ControllerSlot(slot)
			controllers = append(controllers, node{name, str(host, "private_ip")})
		}
		if err != nil {
			return nil, err
		}
	}
	if len(members) == 0 {
		members = controllers
	}
	if len(members) == 0 {
		return nil, errors.New("attempt plan has no TerraBase member hosts")
	}
	return members, nil
}

// deriveTerraBase is the cell's first TerraBase profile.
//
// TerraBase is ready only once it fetched its auth issuer's signing keys,
// and ts-auth is ready only once TerraBase is (the gru-1 re-found's
// deadlock). A cell other than the home cell trusts the home cell's ts-auth,
// which already serves, so its profile carries the issuer from the start,
// and audiences for both its own API and the home API that issuer's tokens
// name. The home cell's own ts-auth cannot serve yet: its profile carries
// only the Management credential, and a later root-signed amendment adds
// the issuer once ts-auth serves.
func deriveTerraBase(cell catalog.Entry, plan Object) (Object, error) {
	members, err := terraBaseMembers(cell, plan)
	if err != nil {
		return nil, err
	}
	region, err := naming.RegionCell(cell.Cell).Name()
	if err != nil {
		return nil, err
	}
	var peers []string
	for _, m := range members {
		peers = append(peers, m.name+"="+m.ip+":"+strconv.Itoa(terraBasePeerPort))
	}
	env := Object{
		"TERRABASE_REGION":      region,
		terrabase.EnvPeerPort:   strconv.Itoa(terraBasePeerPort),
		terrabase.EnvClientPort: strconv.Itoa(terraBaseClientPort),
		terrabase.EnvPeers:      strings.Join(peers, ","),
		// One member writes the catalog; the others follow it (TerraBase
		// decision 0009). Naming it on every member makes it the primary.
		"TERRABASE_CATALOG_PRIMARY": members[0].name,
	}
	profile := Object{"resources": Object{"cpu": 1, "memory_bytes": 4 << 30, "disk_bytes": 20 << 30}, "env": env}
	home, _ := catalog.Lookup(catalog.Bootstrap)
	if cell.Cell != home.Cell {
		env["TERRABASE_AUTH_ISSUER"] = authOrigin(home) + "/terrascale"
		env["TERRABASE_AUTH_AUDIENCE"] = apiURL(cell) + "," + apiURL(home)
		return profile, nil
	}
	// The bootstrap path before ts-auth serves; the host delivers it as an
	// in-memory file from Vault (TS-745).
	vault := str(object(plan["resource_ids"]), "vault")
	if vault == "" {
		return nil, errors.New("attempt plan binds no vault for TerraBase's Management credential")
	}
	profile["secrets"] = Object{"TERRABASE_MANAGEMENT_CREDENTIAL_FILE": Object{"vault": vault,
		"name": region + "-terrabase-management-credential"}}
	return profile, nil
}

// deriveTSAuth is the cell's ts-auth profile and service spec: its own
// regional origin and API, storage on the TerraBase members of terraBase
// (the primary preferred) trusting the attempt's member CA, and its secrets
// as <cell>-ts-auth-* in the plan's Vault. tsauth.ValidateProfile accepts
// only the home cell's until its contract takes any catalog cell.
func (a *Attempt) deriveTSAuth(cell catalog.Entry, plan Object, terraBase map[string]string) (Object, Object, error) {
	vault := str(object(plan["resource_ids"]), "vault")
	if vault == "" {
		return nil, nil, errors.New("attempt plan binds no vault for ts-auth's secrets")
	}
	ca, err := os.ReadFile(a.Path("material", "terrabase-member-ca.pem"))
	if err != nil {
		return nil, nil, fmt.Errorf("ts-auth trusts the TerraBase member CA: %w", err)
	}
	members, err := terrabase.ParseProfile(terraBase)
	if err == nil && members.ClientPort == 0 {
		err = errors.New("the TerraBase profile sets no client port")
	}
	if err != nil {
		return nil, nil, fmt.Errorf("ts-auth stores through TerraBase's client port: %w", err)
	}
	var endpoints []string
	for _, peer := range members.Peers {
		endpoints = append(endpoints, "https://"+peer.Address.Addr().String()+":"+strconv.Itoa(members.ClientPort))
	}
	env := Object{
		tsauth.EnvPublicOrigin: authOrigin(cell), tsauth.EnvAPIURL: apiURL(cell), tsauth.EnvAudiences: apiURL(cell),
		tsauth.EnvAPIEndpoints: strings.Join(endpoints, ";"), tsauth.EnvAPICA: string(ca),
		tsauth.EnvAPIFailover: strconv.FormatBool(len(endpoints) > 1), tsauth.EnvDatabase: tsauth.Database,
		tsauth.EnvDashboardRedirectURIs: tsauth.DashboardRedirectURI, tsauth.EnvDashboardLogoutURIs: tsauth.DashboardLogoutURI,
		"TS_AUTH_SMTP_HOST": "smtp.email." + cell.OCIRegion + ".oci.oraclecloud.com", "TS_AUTH_SMTP_PORT": "587",
		"TS_AUTH_SMTP_FROM_ADDRESS": "noreply@terrascale.tech", "TS_AUTH_SMTP_CHECK_REVOCATION": "false",
	}
	name, err := naming.RegionCell(cell.Cell).Name()
	if err != nil {
		return nil, nil, err
	}
	secrets := Object{}
	for _, key := range slices.Concat(tsauth.Secrets, []string{"TS_AUTH_SMTP_USERNAME", "TS_AUTH_SMTP_PASSWORD"}) {
		secrets[key] = Object{"vault": vault, "name": tsauth.SecretName(name, key)}
	}
	profile := Object{"resources": Object{"cpu": 1, "memory_bytes": 1 << 30, "disk_bytes": 2 << 30}, "env": env, "secrets": secrets}
	spec := Object{"role": tsauth.Role, "environment": "canary", "kind": "stateless",
		"replicas": Object{"min": tsauth.Replicas, "max": tsauth.Replicas}, "placement": Object{"max_per_failure_domain": 1},
		"rollout": Object{"max_surge": 1, "max_unavailable": 1}}
	return profile, spec, nil
}

// profileEnv reads a profile's env.
func (a *Attempt) profileEnv(path string) map[string]string {
	env := map[string]string{}
	for key, value := range object(a.read(path)["env"]) {
		env[key], _ = value.(string)
	}
	return env
}

// grantHosts plans a host grant for every controller node of the plan with
// the colocated roles the cell delivers in services: ts-auth, and
// TerraBase where the TerraBase profile lists the node as a member. A grant
// gives a host credentials, so a root signs it. A grant the spec already
// holds plans nothing, so a rerun changes nothing.
func (a *Attempt) grantHosts(services []any, apply func(candidate, signed string, root bool)) {
	roles := map[string]string{}
	for _, v := range services {
		roles[str(object(v), "role")] = str(object(v), "profile")
	}
	var members terrabase.Profile
	if path, ok := roles[terrabase.Role]; ok {
		var err error
		members, err = terrabase.ParseProfile(a.profileEnv(path))
		a.fail(err)
	}
	plan := a.read(a.Plan())
	cell := a.Cell()
	if a.err != nil {
		return
	}
	hosts := hostMap(plan)
	cli, config := a.Path("release", OperatorCLI), filepath.Join(a.OperatorDirectory(), "operator.json")
	for _, slot := range Slots {
		name, err := naming.RegionCell(cell.Cell).ControllerSlot(slot)
		a.fail(err)
		ip := str(hosts[slot], "private_ip")
		var granted []string
		if _, ok := roles[tsauth.Role]; ok {
			granted = append(granted, tsauth.Role)
		}
		if _, ok := members.Member(name, ip); ok {
			granted = append(granted, terrabase.Role)
		}
		if a.err != nil || len(granted) == 0 {
			continue
		}
		slices.Sort(granted)
		candidate, signed := a.Path("services", "grant-"+name+".candidate.json"), a.Path("services", "grant-"+name+".signed.json")
		a.sudo(false, "rm", "-f", "--", candidate, signed)
		a.sudo(true, cli, "service", "grant-host", "--config", config, "--node", name, "--private-ip", ip,
			"--roles", strings.Join(granted, ","), "--environment", "canary", "--controller", slot, "--out", candidate)
		if a.err == nil && exists(candidate) {
			apply(candidate, signed, true)
		}
	}
}

// deriveServices writes the profiles of the cell's roles the attempt config
// does not name, from the attempt's bound plan, and returns their paths.
func (a *Attempt) deriveServices(terraBaseConfigured string, tsAuth bool) (map[string][2]string, error) {
	plan := a.read(a.Plan())
	cell := a.Cell()
	if a.err != nil {
		return nil, a.err
	}
	paths := map[string][2]string{}
	terraBase := terraBaseConfigured
	if terraBase == "" {
		profile, err := deriveTerraBase(cell, plan)
		if err != nil {
			return nil, err
		}
		terraBase = a.derivedProfile(terrabase.Role)
		a.writeJSON(terraBase, profile)
		paths[terrabase.Role] = [2]string{terraBase}
	}
	if tsAuth {
		env := a.profileEnv(terraBase)
		if a.err != nil {
			return nil, a.err
		}
		profile, spec, err := a.deriveTSAuth(cell, plan, env)
		if err != nil {
			return nil, err
		}
		path, specPath := a.derivedProfile(tsauth.Role), a.Path("services", tsauth.Role+".service.json")
		a.writeJSON(path, profile)
		a.writeJSON(specPath, spec)
		paths[tsauth.Role] = [2]string{path, specPath}
	}
	return paths, a.err
}

func (a *Attempt) PhaseServices() {
	services, err := a.cellServices()
	if a.fail(err); a.err != nil || len(services) == 0 {
		return
	}
	// A role names files the phase deletes as root.
	for _, v := range services {
		service := object(v)
		if !serviceRole.MatchString(str(service, "role")) || str(service, "profile") == "" {
			a.fail(fmt.Errorf("attempt config services need a valid role and a profile"))
			return
		}
	}
	dir := a.Path("services")
	a.mkdir(dir)
	// Every run issues a fresh delegation, so a resumed attempt never signs
	// with an expired one.
	delegation := filepath.Join(dir, "spec-delegation.signed.json")
	if err := os.Remove(delegation); !errors.Is(err, os.ErrNotExist) {
		a.fail(err)
	}
	issued := a.Now().UTC().Truncate(time.Second).Add(-time.Minute)
	a.release("sign-spec-delegation", "--subject-public-key", a.trust("release_leaf_public"), "--root-key", a.trust("root_public"), "--signing-key", a.trust("root_private"), "--deployment-id", a.Deployment, "--cell", a.Cell().Name(), "--environment", "canary", "--issued-at", issued.Format(time.RFC3339), "--expires-at", issued.Add(7*24*time.Hour).Format(time.RFC3339), "--out", delegation)
	cli, config := a.Path("release", OperatorCLI), filepath.Join(a.OperatorDirectory(), "operator.json")
	apply := func(candidate, signed string, root bool) {
		if root {
			a.release("sign-spec", "--candidate", candidate, "--root", "--root-key", a.trust("root_public"), "--signing-key", a.trust("root_private"), "--out", signed)
		} else {
			a.release("sign-spec", "--candidate", candidate, "--delegation", delegation, "--root-key", a.trust("root_public"), "--signing-key", a.trust("release_leaf_private"), "--out", signed)
		}
		a.sudo(false, cli, "service", "apply", "--config", config, "--file", signed)
	}
	for _, v := range services {
		service := object(v)
		role, profile, spec := str(service, "role"), str(service, "profile"), str(service, "spec")
		// Every run plans from the cell's current spec, so a spec another
		// change made stale is never reapplied.
		candidate, signed := filepath.Join(dir, role+".candidate.json"), filepath.Join(dir, role+".signed.json")
		a.sudo(false, "rm", "-f", "--", candidate, signed)
		args := []string{cli, "service", "add", "--config", config, "--role", role, "--profile", profile, "--out", candidate}
		if spec != "" {
			args = append(args, "--spec", spec)
		}
		plan := a.sudo(true, args...)
		if a.err != nil {
			return
		}
		if !exists(candidate) {
			continue
		}
		// The leader's plan names what only a root may sign, such as a
		// role's Vault secrets; the attempt holds the root key.
		var planned struct {
			RootRequired []string `json:"root_required"`
		}
		if a.fail(json.Unmarshal([]byte(plan), &planned)); a.err != nil {
			return
		}
		apply(candidate, signed, len(planned.RootRequired) != 0)
	}
	a.grantHosts(services, apply)
}

// cellServices lists the services the services phase applies: TerraBase and
// ts-auth from their attempt settings, or derived from the plan when the
// config names them neither there nor in services, then the configured
// services. A role set both ways is refused rather than one source silently
// winning.
func (a *Attempt) cellServices() ([]any, error) {
	if (str(a.Config, "ts_auth_profile") == "") != (str(a.Config, "ts_auth_service") == "") {
		return nil, errors.New("attempt config needs ts_auth_profile and ts_auth_service together")
	}
	configured := rows(a.Config["services"])
	named := func(role string) string {
		for _, v := range configured {
			if str(object(v), "role") == role {
				return str(object(v), "profile")
			}
		}
		return ""
	}
	roles := []string{terrabase.Role, tsauth.Role}
	own := map[string][2]string{
		terrabase.Role: {str(a.Config, "terrabase_profile")},
		tsauth.Role:    {str(a.Config, "ts_auth_profile"), str(a.Config, "ts_auth_service")},
	}
	for _, role := range roles {
		if own[role][0] != "" && named(role) != "" {
			return nil, fmt.Errorf("attempt config names %s in services and in its own settings; keep one", role)
		}
	}
	terraBase := cmp.Or(own[terrabase.Role][0], named(terrabase.Role))
	if tsAuth := own[tsauth.Role][0] == "" && named(tsauth.Role) == ""; terraBase == "" || tsAuth {
		derived, err := a.deriveServices(terraBase, tsAuth)
		if err != nil {
			return nil, err
		}
		maps.Copy(own, derived)
	}
	var services []any
	for _, role := range roles {
		if own[role][0] == "" {
			continue
		}
		service := Object{"role": role, "profile": own[role][0]}
		if own[role][1] != "" {
			service["spec"] = own[role][1]
		}
		services = append(services, service)
	}
	return append(services, configured...), nil
}

func ParseProfile(env map[string]string) (Profile, error) {
	for _, key := range hostOwned {
		if _, set := env[key]; set {
			return Profile{}, fmt.Errorf("terrabase profile must not set %s", key)
		}
	}
	profile := Profile{AdminPort: DefaultAdminPort}
	var err error
	if raw, set := env[EnvAdminPort]; set {
		if profile.AdminPort, err = parsePort(raw); err != nil {
			return Profile{}, fmt.Errorf("%s: %w", EnvAdminPort, err)
		}
	}
	if profile.PeerPort, err = parsePort(env[EnvPeerPort]); err != nil {
		return Profile{}, fmt.Errorf("%s: %w", EnvPeerPort, err)
	}
	if raw, set := env[EnvClientPort]; set {
		if profile.ClientPort, err = parsePort(raw); err != nil {
			return Profile{}, fmt.Errorf("%s: %w", EnvClientPort, err)
		}
	}
	if profile.Peers, err = ParsePeers(env[EnvPeers]); err != nil {
		return Profile{}, err
	}
	for _, peer := range profile.Peers {
		if int(peer.Address.Port()) != profile.PeerPort {
			return Profile{}, fmt.Errorf("%s: peer %s does not use %s", EnvPeers, peer.Name, EnvPeerPort)
		}
	}
	if profile.AdminPort == profile.PeerPort || profile.ClientPort == profile.AdminPort || profile.ClientPort == profile.PeerPort {
		return Profile{}, errors.New("terrabase admin, peer and client ports must differ")
	}
	return profile, nil
}

func (p Profile) Peer(node string) (Peer, bool) {
	index := slices.IndexFunc(p.Peers, func(peer Peer) bool { return peer.Name == node })
	if index < 0 {
		return Peer{}, false
	}
	return p.Peers[index], true
}

// Member returns the member a host runs: the one named after its node, or
// else the one at the host's private address, which outlives a rename of
// the node (TS-609 keeps member names such as gru-1-ctl-1). Members share
// one peer port, so an address names at most one.
func (p Profile) Member(node, address string) (Peer, bool) {
	if peer, ok := p.Peer(node); ok {
		return peer, true
	}
	index := slices.IndexFunc(p.Peers, func(peer Peer) bool { return peer.Address.Addr().String() == address })
	if index < 0 {
		return Peer{}, false
	}
	return p.Peers[index], true
}

// ParsePeers parses name=ip:port entries with unique names and addresses.
func ParsePeers(raw string) ([]Peer, error) {
	if raw == "" {
		return nil, fmt.Errorf("%s is required", EnvPeers)
	}
	entries := strings.Split(raw, ",")
	if len(entries) > 64 {
		return nil, fmt.Errorf("%s lists more than 64 members", EnvPeers)
	}
	peers := make([]Peer, 0, len(entries))
	for _, entry := range entries {
		name, address, found := strings.Cut(entry, "=")
		addrPort, err := netip.ParseAddrPort(address)
		if !found || !nameRE.MatchString(name) || err != nil || addrPort.String() != address ||
			addrPort.Port() == 0 || !addrPort.Addr().IsValid() || addrPort.Addr().IsUnspecified() {
			return nil, fmt.Errorf("%s entry %q is not name=ip:port", EnvPeers, entry)
		}
		if addrPort.Addr().Zone() != "" || addrPort.Addr().IsLinkLocalUnicast() || addrPort.Addr().IsLinkLocalMulticast() {
			return nil, fmt.Errorf("%s entry %q: zone identifiers and link-local addresses are not supported", EnvPeers, entry)
		}
		if slices.ContainsFunc(peers, func(p Peer) bool { return p.Name == name || p.Address == addrPort }) {
			return nil, fmt.Errorf("%s repeats member %q or its address", EnvPeers, name)
		}
		peers = append(peers, Peer{Name: name, Address: addrPort})
	}
	return peers, nil
}

func parsePort(raw string) (int, error) {
	port, err := strconv.Atoi(raw)
	if err != nil || port < 1 || port > 65535 || strconv.Itoa(port) != raw {
		return 0, errors.New("must be a port between 1 and 65535")
	}
	return port, nil
}

func ValidateProfile(cell string, args []string, env map[string]string, secrets map[string]vaultsecret.Ref) error {
	if _, ok := catalog.LookupName(cell); !ok {
		return fmt.Errorf("ts-auth needs a catalog cell, not %q", cell)
	}
	if len(args) != 0 {
		return errors.New("ts-auth profile sets its settings only through env")
	}
	if slices.ContainsFunc(Secrets, func(key string) bool { _, ok := secrets[key]; return !ok }) {
		return fmt.Errorf("ts-auth profile secrets must name %s", strings.Join(Secrets, ", "))
	}
	for key := range secrets {
		if !slices.Contains(Secrets, key) && !slices.Contains(OptionalSecrets, key) {
			return fmt.Errorf("ts-auth profile secrets may add only %s, not %s", strings.Join(OptionalSecrets, ", "), key)
		}
	}
	for _, key := range slices.Concat(Secrets, OptionalSecrets, optionalSecrets, []string{EnvListen, EnvBundleExtract}) {
		if _, set := env[key]; set {
			return fmt.Errorf("ts-auth profile must not set %s", key)
		}
	}
	for key, want := range map[string]string{EnvPublicOrigin: PublicOrigin(cell), EnvAPIURL: APIURL(cell), EnvDatabase: Database, EnvAudiences: APIURL(cell),
		EnvDashboardRedirectURIs: DashboardRedirectURI, EnvDashboardLogoutURIs: DashboardLogoutURI} {
		if env[key] != want {
			return fmt.Errorf("ts-auth profile must set %s=%s", key, want)
		}
	}
	return nil
}

// ValidateMembers checks a ts-auth profile's private TerraBase endpoints
// against the cell's TerraBase profile terraBase: each one is
// https://<member IP>:<client port> of a member TERRABASE_PEERS lists, at
// most once, and EnvAPICA holds 1 to 4 PEM CA certificates and nothing else.
// Several endpoints need EnvAPIFailover=true. A profile without endpoints and
// CA stores through EnvAPIURL. Without a terrabase
// profile, as in an identity-only controller config whose first cell spec
// brings it, only the pairing and the CA are checked.
func ValidateMembers(env, terraBase map[string]string) error {
	endpoints, roots := env[EnvAPIEndpoints], env[EnvAPICA]
	if endpoints == "" && roots == "" {
		return nil
	}
	if endpoints == "" || roots == "" {
		return fmt.Errorf("ts-auth profile sets %s and %s together", EnvAPIEndpoints, EnvAPICA)
	}
	if !caCertificates(roots) {
		return fmt.Errorf("%s must hold 1 to 4 PEM CA certificates and nothing else", EnvAPICA)
	}
	if failover, set := env[EnvAPIFailover]; set && failover != "true" && failover != "false" ||
		strings.Contains(endpoints, ";") && failover != "true" {
		return fmt.Errorf("%s lists several members only with %s=true", EnvAPIEndpoints, EnvAPIFailover)
	}
	if len(terraBase) == 0 {
		return nil
	}
	members, err := terrabase.ParseProfile(terraBase)
	if err != nil || members.ClientPort == 0 {
		return fmt.Errorf("%s needs a terrabase profile with %s", EnvAPIEndpoints, terrabase.EnvClientPort)
	}
	seen := map[string]bool{}
	for _, endpoint := range strings.Split(endpoints, ";") {
		member := slices.ContainsFunc(members.Peers, func(peer terrabase.Peer) bool {
			return endpoint == "https://"+netip.AddrPortFrom(peer.Address.Addr(), uint16(members.ClientPort)).String()
		})
		if !member || seen[endpoint] {
			return fmt.Errorf("%s must list distinct https://IP:%d client endpoints of the %s, not %q",
				EnvAPIEndpoints, members.ClientPort, terrabase.EnvPeers, endpoint)
		}
		seen[endpoint] = true
	}
	return nil
}

func RegionCell(region string) Cell { return Cell{Region: region, Index: 1} }

// Name returns the cell name, e.g. gru-1.
func (c Cell) Name() (string, error) {
	return valid(fmt.Sprintf("%s-%d", strings.ToLower(c.Region), c.Index))
}

// Image returns the name of the cell's qualified ARM64 host image, e.g.
// gru-1-arm64. A new image import reuses the name; the source revision and
// digest belong in its signed receipt.
func (c Cell) Image() (string, error) {
	name, err := c.Name()
	if err != nil {
		return "", err
	}
	return name + "-arm64", nil
}

// Node returns the name of the region's n-th node, e.g. ts-gru-1.
func (c Cell) Node(n int) (string, error) {
	return valid(fmt.Sprintf("ts-%s-%d", strings.ToLower(c.Region), n))
}

// Server returns the name of the cell's n-th server of role, e.g. gru-1-ctl-1.
func (c Cell) Server(role string, n int) (string, error) {
	return valid(fmt.Sprintf("%s-%d-%s-%d", strings.ToLower(c.Region), c.Index, role, n))
}

// PoolServer returns the name of the n-th host of a node pool, e.g.
// gru-1-pool-app-3. A pool name is 2 to 12 lower-case letters and digits,
// starting with a letter.
func (c Cell) PoolServer(pool string, n int) (string, error) {
	return valid(fmt.Sprintf("%s-%d-pool-%s-%d", strings.ToLower(c.Region), c.Index, pool, n))
}

// ControllerSlot returns the server name of a signed controller slot:
// controller-a, -b and -c are the region's nodes 1, 2 and 3 (ts-sfo-1). GRU
// keeps ctl-1, -2 and -3 (gru-1-ctl-1) until its servers are renamed: a
// controller refuses a NATS store of another server name.
func (c Cell) ControllerSlot(slot string) (string, error) {
	if strings.ToUpper(c.Region) == catalog.GRU {
		return c.slot(slot, "controller-", Controller)
	}
	letter, ok := strings.CutPrefix(slot, "controller-")
	if !ok || len(letter) != 1 || letter[0] < 'a' || letter[0] > 'z' {
		return "", fmt.Errorf("%w: controller-slot %q", ErrName, slot)
	}
	return c.Node(int(letter[0]-'a') + 1)
}

// MemberSlot returns the server name of a regional plan's database host
// slot: member-a and -b are db-1 and -2.
func (c Cell) MemberSlot(slot string) (string, error) { return c.slot(slot, "member-", Member) }

func (c Cell) slot(slot, prefix, role string) (string, error) {
	letter, ok := strings.CutPrefix(slot, prefix)
	if !ok || len(letter) != 1 || letter[0] < 'a' || letter[0] > 'z' {
		return "", fmt.Errorf("%w: %sslot %q", ErrName, prefix, slot)
	}
	return c.Server(role, int(letter[0]-'a')+1)
}

func Validate(name string) error {
	match := nodeScheme.FindStringSubmatch(name)
	if match == nil {
		match = scheme.FindStringSubmatch(name)
	}
	if match == nil || !catalog.IsCell(strings.ToUpper(match[1])) {
		return fmt.Errorf("%w: %q", ErrName, name)
	}
	return nil
}

// IsNode reports whether name is a node of region, ts-<region>-<n> (not its
// data volume).
func IsNode(name, region string) bool {
	match := nodeScheme.FindStringSubmatch(name)
	return match != nil && match[1] == strings.ToLower(region) && !strings.HasSuffix(name, "-data") &&
		catalog.IsCell(strings.ToUpper(region))
}

// NATSServer is a NATS server name: a catalog cell's controller slot gets its
// server name (gru-1-ctl-1); lab cells and instances outside the scheme keep
// <cell>-<instance>.
func NATSServer(cell, instance string) string {
	if name, err := RegionCell(cell).ControllerSlot(instance); err == nil {
		return name
	}
	return cell + "-" + instance
}

func valid(name string) (string, error) {
	if err := Validate(name); err != nil {
		return "", err
	}
	return name, nil
}

func (e Entry) Name() string { return strings.ToLower(e.Cell) }

const (
	GRU = "GRU"
	SFO = "SFO"
	FRA = "FRA"
	// Bootstrap is the only cell that may found a deployment until a
	// separately reviewed migration exists.
	Bootstrap = GRU
)

// entries is ordered: placement assigns permanent members in this order.
var entries = [...]Entry{
	{Cell: GRU, OCIRegion: "sa-saopaulo-1", OCIRegionKey: "GRU", City: "São Paulo", Country: "BR", Latitude: -23.43, Longitude: -46.47},
	{Cell: SFO, OCIRegion: "us-sanjose-1", OCIRegionKey: "SJC", City: "San Jose", Country: "US", Latitude: 37.34, Longitude: -121.89},
	{Cell: FRA, OCIRegion: "eu-frankfurt-1", OCIRegionKey: "FRA", City: "Frankfurt", Country: "DE", Latitude: 50.11, Longitude: 8.68},
	{Cell: "AMS", OCIRegion: "eu-amsterdam-1", OCIRegionKey: "AMS", City: "Amsterdam", Country: "NL", Latitude: 52.37, Longitude: 4.90},

func LookupName(name string) (Entry, bool) {
	for _, entry := range entries {
		if entry.Name() == name {
			return entry, true
		}
	}
	return Entry{}, false
}

// Lookup returns the entry for an exact upper-case cell code.
func Lookup(cell string) (Entry, bool) {
	for _, entry := range entries {
		if entry.Cell == cell {
			return entry, true
		}
	}
	return Entry{}, false
}

// IsCell reports whether cell is an exact upper-case supported cell code.
func IsCell(cell string) bool {
	_, ok := Lookup(cell)
	return ok
}

