func (c command) verifyImageProduction(args []string) error {
	flags := flag.NewFlagSet("verify-image-production", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	imageFile := flags.String("image-file", "", "exact final QCOW2 image")
	qualificationPath := flags.String("qualification", "", "retained binary CI qualification manifest")
	rootPath := flags.String("root-key", "", "existing trusted root public key PEM")
	evidenceDir := flags.String("production-evidence-dir", "", "retained signed final image evidence; default qualification sibling image-production")
	cell := flags.String("cell", "", "target region")
	architecture := flags.String("arch", "", "image architecture")
	environment := flags.String("environment", "production", "target admitted environment")
	receiptPath := flags.String("image-receipt", "", "signed image receipt for pre-launch admission")
	delegationPath := flags.String("delegation", "", "image receipt release delegation")
	imageOCID := flags.String("image-ocid", "", "independently retained OCI image identity")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *imageFile == "" || *qualificationPath == "" || *rootPath == "" || !validRegion(*cell) ||
		(*architecture != "amd64" && *architecture != "arm64") || !validEnvironment(*environment) || flags.NArg() != 0 {
		return errors.New("verify-image-production requires --image-file, --qualification, --root-key, --cell, and --arch")
	}
	if (*receiptPath != "" || *delegationPath != "" || *imageOCID != "") &&
		(*receiptPath == "" || *delegationPath == "" || *imageOCID == "") {
		return errors.New("--image-receipt, --delegation, and --image-ocid must be supplied together")
	}
	qualification, digest, err := readQualification(*qualificationPath)
	if err != nil {
		return err
	}
	imageDigest, _, err := c.hashQcow2(*imageFile)
	if err != nil {
		return err
	}
	root, err := readRootPublicKey(*rootPath)
	if err != nil {
		return err
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		return err
	}
	if *evidenceDir == "" {
		*evidenceDir = filepath.Join(filepath.Dir(*qualificationPath), "image-production")
	}
	expected := release.ProductionExpectation{SourceRevision: qualification.SourceRevision, ArtifactSHA256: imageDigest,
		QualificationSHA256: digest, Cell: *cell, Environment: *environment,
		Runtime: release.ProductionRuntime, Architecture: *architecture, Role: "orchestrator"}
	if *receiptPath != "" {
		wire, err := readBoundedRegular(*receiptPath, trust.MaxEnvelopeBytes)
		if err != nil {
			return err
		}
		delegation, err := readBoundedRegular(*delegationPath, trust.MaxEnvelopeBytes)
		if err != nil {
			return err
		}
		image, err := release.VerifyImageCurrent(wire, delegation, roots, release.ImageExpectation{
			Environment: *environment, LogicalRegion: *cell, Architecture: *architecture, OCIImageOCID: *imageOCID}, time.Now().UTC())
		if err != nil {
			return err
		}
		receipt := image.Receipt()
		if receipt.ImageSHA256 != imageDigest || receipt.SourceRevision != qualification.SourceRevision || receipt.QualificationSHA256 != digest {
			return fmt.Errorf("%w: signed image differs from retained disk or CI qualification", release.ErrExpectationMismatch)
		}
	}
	return c.verifyProductionCandidate(*evidenceDir, roots, expected, time.Now().UTC())
}

func (c command) verifyProductionCandidate(evidenceDir string, roots trust.Keyring, expected release.ProductionExpectation, now time.Time) error {
	directory := filepath.Join(evidenceDir, expected.Cell, expected.Architecture)
	wire, err := readBoundedRegular(filepath.Join(directory, "production.json"), trust.MaxEnvelopeBytes)
	if err != nil {
		return fmt.Errorf("%w: %s %s record: %w", release.ErrProductionQualification, expected.Cell, expected.Architecture, err)
	}
	delegation, err := readBoundedRegular(filepath.Join(directory, "delegation.json"), trust.MaxEnvelopeBytes)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("%w: qualification delegation: %w", release.ErrProductionQualification, err)
	}
	if _, err := release.VerifyProductionCurrent(wire, delegation, roots, expected, time.Now().UTC()); err != nil {
		return fmt.Errorf("%s %s current admission: %w", expected.Cell, expected.Architecture, err)
	}
	qualification, err := release.VerifyProductionCurrent(wire, delegation, roots, expected, now)
	if err != nil {
		return fmt.Errorf("%s %s: %w", expected.Cell, expected.Architecture, err)
	}
	for _, evidence := range qualification.Evidence {
		file, err := openRegular(filepath.Join(evidenceDir, "objects", evidence.SHA256))
		if err != nil {
			return fmt.Errorf("%w: %s %s evidence: %w", release.ErrProductionQualification, expected.Cell, evidence.Gate, err)
		}
		if err := errors.Join(release.VerifyProductionEvidence(c.ctx, file, evidence, expected), file.Close()); err != nil {
			return fmt.Errorf("%s %s retained evidence: %w", expected.Cell, evidence.Gate, err)
		}
	}
	return c.ctx.Err()
}

func readQualification(path string) (release.Qualification, string, error) {
	wire, err := readBoundedRegular(path, release.MaxQualificationBytes)
	if err != nil {
		return release.Qualification{}, "", err
	}
	return release.DecodeQualification(wire)
}

func readBoundedRegular(path string, maximum int64) ([]byte, error) {
	file, err := openRegular(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if info.Size() < 0 || info.Size() > maximum {
		return nil, fmt.Errorf("%s exceeds the %d-byte limit", filepath.Base(path), maximum)
	}
	return io.ReadAll(io.LimitReader(file, maximum+1))
}

func openRegular(path string) (*os.File, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return nil, fmt.Errorf("stat %s: %w", filepath.Base(path), err)
	}
	if !info.Mode().IsRegular() {
		return nil, fmt.Errorf("%s must be a regular file", filepath.Base(path))
	}
	file, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", filepath.Base(path), err)
	}
	opened, err := file.Stat()
	if err != nil || !os.SameFile(info, opened) {
		file.Close()
		return nil, fmt.Errorf("%s changed while opening", filepath.Base(path))
	}
	return file, nil
}

func (c command) hashQcow2(path string) (string, int64, error) {
	if err := c.ctx.Err(); err != nil {
		return "", 0, err
	}
	file, err := openRegular(path)
	if err != nil {
		return "", 0, err
	}
	defer file.Close()
	magic := make([]byte, len(imageMagicQcow2))
	if _, err := io.ReadFull(file, magic); err != nil || string(magic) != imageMagicQcow2 {
		return "", 0, errors.New("image must be a QCOW2 disk")
	}
	if _, err := file.Seek(0, io.SeekStart); err != nil {
		return "", 0, err
	}
	digest, bytes, err := c.hashArtifact(file)
	return hex.EncodeToString(digest), bytes, err
}

func (c command) hashArtifact(reader io.Reader) ([]byte, int64, error) {
	hash := sha256.New()
	count, err := io.Copy(hash, commandio.Reader(c.ctx, reader))
	if err != nil {
		return nil, count, err
	}
	return hash.Sum(nil), count, nil
}

func VerifyProductionCurrent(wire, delegationWire []byte, roots trust.Keyring, expected ProductionExpectation, now time.Time) (ProductionQualification, error) {
	var qualification ProductionQualification
	gates := []string{"runtime-ha", "workload-safety"}
	schema := ProductionQualificationSchema
	if expected.Role == FoundationWriterRole {
		schema = FoundationWriterQualificationSchema
		gates = append(gates, RootCredentialBoundaryGate)
	}
	validRuntime := expected.Runtime == ProductionRuntime
	if expected.Role == FoundationWriterRole {
		validRuntime = validRuntime && ValidOCIImageIDForRegion(expected.ImageOCID, expected.Cell)
	}
	if expected.Role == "netbird-manager" || expected.Runtime == NetBirdProductionRuntime {
		validRuntime = expected.Role == "netbird-manager" && expected.Runtime == NetBirdProductionRuntime &&
			expected.Cell == "GRU" && expected.Architecture == "arm64"
		gates = []string{"netbird-foundation", "netbird-recovery"}
	}
	if !ValidSourceRevision(expected.SourceRevision) || !digestPattern.MatchString(expected.ArtifactSHA256) ||
		!digestPattern.MatchString(expected.QualificationSHA256) || !ValidRegion(expected.Cell) ||
		!ValidEnvironment(expected.Environment) || !validRuntime ||
		expected.Architecture != "amd64" && expected.Architecture != "arm64" || !serviceRolePattern.MatchString(expected.Role) {
		return qualification, fmt.Errorf("%w: candidate scope", ErrProductionQualification)
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	var payload []byte
	if len(delegationWire) == 0 {
		payload, err = trust.VerifyCurrent(envelope, ProductionQualificationScope(expected), roots, now, policy)
	} else {
		var delegationEnvelope trust.Envelope
		delegationEnvelope, err = trust.DecodeEnvelope(delegationWire)
		if err == nil {
			var delegation trust.VerifiedDelegation
			delegation, err = trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, policy)
			if err == nil {
				payload, err = trust.VerifyDelegatedCurrent(envelope, ProductionQualificationScope(expected), delegation, now, policy)
			}
		}
	}
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if err := protocol.DecodeStrict(payload, &qualification, trust.MaxPayloadBytes); err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if qualification.Schema != schema || qualification.Candidate != expected || len(qualification.Evidence) != len(gates) {
		return qualification, fmt.Errorf("%w: candidate or required gates", ErrProductionQualification)
	}
	for index, gate := range gates {
		evidence := qualification.Evidence[index]
		if evidence.Gate != gate || !digestPattern.MatchString(evidence.SHA256) ||
			evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || evidence.CompletedAt.IsZero() ||
			evidence.CompletedAt.After(envelope.IssuedAt) {
			return qualification, fmt.Errorf("%w: %s evidence", ErrProductionQualification, gate)
		}
	}
	return qualification, nil
}

func VerifyProductionEvidence(ctx context.Context, reader io.Reader, evidence ProductionGateEvidence, expected ProductionExpectation) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if reader == nil || evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || !digestPattern.MatchString(evidence.SHA256) {
		return fmt.Errorf("%w: retained %s evidence metadata", ErrProductionQualification, evidence.Gate)
	}
	digest := sha256.New()
	var body bytes.Buffer
	var destination io.Writer = digest
	if evidence.Gate == RootCredentialBoundaryGate {
		destination = io.MultiWriter(digest, &body)
	}
	count, err := io.Copy(destination, io.LimitReader(reader, evidence.Bytes+1))
	if err != nil {
		return fmt.Errorf("read retained %s evidence: %w", evidence.Gate, err)
	}
	if count != evidence.Bytes || hex.EncodeToString(digest.Sum(nil)) != evidence.SHA256 {
		return fmt.Errorf("%w: retained %s evidence differs from the signed size or SHA-256", ErrProductionQualification, evidence.Gate)
	}
	if evidence.Gate == RootCredentialBoundaryGate {
		var boundary RootCredentialBoundaryEvidence
		if err := protocol.DecodeStrict(body.Bytes(), &boundary, MaxProductionEvidenceBytes); err != nil {
			return fmt.Errorf("%w: root credential boundary evidence: %w", ErrProductionQualification, err)
		}
		if err := boundary.Validate(expected); err != nil {
			return err
		}
		if !boundary.CompletedAt.Equal(evidence.CompletedAt) {
			return fmt.Errorf("%w: root credential boundary completion time", ErrProductionQualification)
		}
	}
	return ctx.Err()
}

func VerifyImageCurrent(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected ImageExpectation, now time.Time,
) (VerifiedImage, error) {
	if err := validateImageExpectation(expected); err != nil {
		return VerifiedImage{}, err
	}
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return VerifiedImage{}, err
	}
	receipt, err := decodeCanonicalPayload[ImageReceipt](envelope.Payload)
	if err != nil {
		return VerifiedImage{}, err
	}
	if err := receipt.Validate(); err != nil {
		return VerifiedImage{}, err
	}
	if err := matchImageExpectation(receipt, expected); err != nil {
		return VerifiedImage{}, err
	}
	scope := ImageScope(receipt, expected.Environment)
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return VerifiedImage{}, fmt.Errorf("verify current release delegation: %w", err)
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, scope, delegation, now, receiptPolicy()); err != nil {
		return VerifiedImage{}, fmt.Errorf("verify current signed image receipt: %w", err)
	}
	productionExpiry, err := verifyImageProduction(receipt, expected.Environment, roots, now)
	if err != nil {
		return VerifiedImage{}, err
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return VerifiedImage{}, err
	}
	if productionExpiry.Before(proof.expiresAt) {
		proof.expiresAt = productionExpiry
	}
	return VerifiedImage{receipt: receipt, proof: proof}, nil
}

func verifyImageProduction(receipt ImageReceipt, environment string, roots trust.Keyring, now time.Time) (time.Time, error) {
	if receipt.Production == nil {
		return time.Time{}, fmt.Errorf("%w: signed image contains no independent qualification", ErrProductionQualification)
	}
	expected := ProductionExpectation{SourceRevision: receipt.SourceRevision, ArtifactSHA256: receipt.ImageSHA256,
		QualificationSHA256: receipt.QualificationSHA256, Cell: receipt.OCIRegion, Environment: environment,
		Runtime: ProductionRuntime, Architecture: receipt.Architecture, Role: "orchestrator"}
	if _, err := VerifyProductionCurrent(receipt.Production.Qualification, receipt.Production.Delegation, roots, expected, now); err != nil {
		return time.Time{}, err
	}
	envelope, err := trust.DecodeEnvelope(receipt.Production.Qualification)
	if err != nil {
		return time.Time{}, err
	}
	expires := envelope.ExpiresAt
	if len(receipt.Production.Delegation) > 0 {
		delegation, err := trust.DecodeEnvelope(receipt.Production.Delegation)
		if err != nil {
			return time.Time{}, err
		}
		if delegation.ExpiresAt.Before(expires) {
			expires = delegation.ExpiresAt
		}
	}
	return expires, nil
