		P95     float64   `json:"p95_us"`
		P99     float64   `json:"p99_us"`
		Max     float64   `json:"max_us"`
	}{s.TS, s.Client, s.SDK, s.SDKVersion, s.Region, s.Op, s.Count, s.Errors, s.P50, s.P95, s.P99, s.Max})
