func New(cfg Config) (*Client, error) {
	if !tokenPattern.MatchString(cfg.Token) {
		return nil, errors.New("terrabase: Token must be a tb_ API key")
	}
	return newClient(cfg)
}

func newClient(cfg Config) (*Client, error) {
	if cfg.Resolver != nil && cfg.BaseURL != "" {
		return nil, errors.New("terrabase: set either Resolver or BaseURL")
	}
	if cfg.Resolver == nil {
		if _, err := parseBaseURL(cfg.BaseURL); err != nil {
			return nil, err
		}
		cfg.Resolver = StaticResolver(cfg.BaseURL)
	}
	hc := &http.Client{Transport: &http.Transport{
		Proxy:             http.ProxyFromEnvironment,
		TLSClientConfig:   &tls.Config{MinVersion: tls.VersionTLS13},
		ForceAttemptHTTP2: true,
		IdleConnTimeout:   90 * time.Second,
	}}
	if cfg.HTTPClient != nil {
		copied := *cfg.HTTPClient
		hc = &copied
	}
	hc.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	c := &Client{resolver: cfg.Resolver, token: cfg.Token, hc: hc, maxRetries: cfg.MaxRetries, maxResponse: cfg.MaxResponseBytes}
	switch {
	case c.maxRetries == 0:
		c.maxRetries = DefaultMaxRetries
	case c.maxRetries < 0:
		c.maxRetries = 0
	}
	if c.maxResponse <= 0 {
		c.maxResponse = DefaultMaxResponseBytes
	}
	return c, nil
}

func parseBaseURL(raw string) (*url.URL, error) {
	u, err := url.Parse(raw)
	if err != nil || u.Host == "" {
		return nil, fmt.Errorf("terrabase: BaseURL %q is not an absolute URL", raw)
	}
	if u.User != nil || u.RawQuery != "" || u.Fragment != "" {
		return nil, errors.New("terrabase: BaseURL must not carry user info, a query or a fragment")
	}
	switch u.Scheme {
	case "https":
	case "http":
		host := u.Hostname()
		if ip := net.ParseIP(host); host != "localhost" && (ip == nil || !ip.IsLoopback()) {
			return nil, errors.New("terrabase: plain HTTP BaseURL is allowed only for loopback hosts")
		}
	default:
		return nil, fmt.Errorf("terrabase: BaseURL scheme %q is not https", u.Scheme)
	}
	escaped := u.EscapedPath()
	if strings.HasSuffix(escaped, "/") {
		u.Path = strings.TrimSuffix(u.Path, "/")
		u.RawPath = strings.TrimSuffix(escaped, "/")
	}
	return u, nil
}

func (c *Client) url(ctx context.Context, segments []string, query url.Values) (string, error) {
	for _, s := range segments {
		if s == "" || s == "." || s == ".." || strings.Contains(s, "/") {
			return "", fmt.Errorf("terrabase: path segment %q is empty, a dot segment or contains a slash", s)
		}
	}
	raw, err := c.resolver.Resolve(ctx)
	if err != nil {
		return "", fmt.Errorf("terrabase: resolve endpoint: %w", err)
	}
	base, err := parseBaseURL(raw)
	if err != nil {
		return "", err
	}
	u := *base
	u.RawPath = u.EscapedPath()
	for _, s := range segments {
		u.Path += "/" + s
		u.RawPath += "/" + url.PathEscape(s)
	}
	u.RawQuery = query.Encode()
	return u.String(), nil
}

// do sends req with the client's retry policy and returns a 2xx response or
// an error. Non-2xx statuses become *APIError.
func (c *Client) do(ctx context.Context, req request) (*response, error) {
	if len(req.body) > MaxRequestBytes {
		return nil, fmt.Errorf("terrabase: request body is %d bytes, over the %d byte limit", len(req.body), MaxRequestBytes)
	}
	target, err := c.url(ctx, req.path, req.query)
	if err != nil {
		return nil, err
	}
	readOnly := req.method == http.MethodGet || req.readOnly
	for attempt := 0; ; attempt++ {
		resp, err := c.send(ctx, req, target)
		if err != nil {
			if !readOnly {
				return nil, fmt.Errorf("%w: %w", ErrCommitUncertain, err)
			}
			if ctx.Err() != nil || !req.replaySafe || attempt >= c.maxRetries {
				return nil, err
			}
			if err := sleep(ctx, backoff(attempt)); err != nil {
				return nil, err
			}
			continue
		}
		if resp.status >= 200 && resp.status < 300 {
			return resp, nil
		}
		apiErr := parseAPIError(resp.status, resp.header, resp.body)
		if !readOnly && apiErr.Code == ErrCommitUncertain {
			return resp, apiErr
		}
		if delay, ok := retryDelay(apiErr, attempt, req.replaySafe); ok && attempt < c.maxRetries {
			if err := sleep(ctx, delay); err != nil {
				return nil, err
			}
			continue
		}
		return resp, apiErr
	}
}

func (c *Client) send(ctx context.Context, req request, target string) (*response, error) {
	method := req.method
	var rd io.Reader
	if req.body != nil {
		rd = bytes.NewReader(req.body)
	}
	hr, err := http.NewRequestWithContext(ctx, method, target, rd)
	if err != nil {
		return nil, fmt.Errorf("terrabase: build request: %w", err)
	}
	for k, v := range req.header {
		hr.Header[k] = v
	}
	hr.Header.Set("Authorization", "Bearer "+cmp.Or(req.token, c.token))
	hr.Header.Set("Accept", "application/json")
	if req.body != nil {
		hr.Header.Set("Content-Type", cmp.Or(req.contentType, "application/json"))
	}
	res, err := c.hc.Do(hr)
	if err != nil {
		return nil, fmt.Errorf("terrabase: %s %s: %w", method, hr.URL.Path, err)
	}
	defer res.Body.Close()
	data, err := io.ReadAll(io.LimitReader(res.Body, c.maxResponse+1))
	if err != nil {
		return nil, fmt.Errorf("terrabase: read %s %s response: %w", method, hr.URL.Path, err)
	}
	if int64(len(data)) > c.maxResponse {
		return nil, fmt.Errorf("terrabase: %s %s response exceeds %d bytes", method, hr.URL.Path, c.maxResponse)
	}
	return &response{status: res.StatusCode, header: res.Header, body: data}, nil
}

// call sends a JSON request and decodes a JSON response into out (if non-nil).
func (c *Client) call(ctx context.Context, req request, in, out any) (*response, error) {
	if in != nil {
		body, err := json.Marshal(in)
		if err != nil {
			return nil, fmt.Errorf("terrabase: encode request: %w", err)
		}
		req.body = body
	}
	resp, err := c.do(ctx, req)
	if err != nil {
		return resp, err
	}
	if out != nil && !(resp.status == http.StatusNoContent && len(bytes.TrimSpace(resp.body)) == 0) {
		if err := decodeExact(resp.body, out); err != nil {
			return resp, fmt.Errorf("terrabase: decode %s response: %w", req.method, err)
		}
		if err := entityid.Model(out); err != nil {
			return resp, fmt.Errorf("terrabase: invalid response: %w", err)
		}
	}
	return resp, nil
}

// decodeExact decodes JSON with UseNumber so numbers stay exact.
func decodeExact(data []byte, v any) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	if err := dec.Decode(v); err != nil {
		return err
	}
	if dec.More() {
		return errors.New("trailing data after JSON value")
	}
	return nil
}

func (c *Client) Database(project, name string) *Database {
	return &Database{c: c, project: project, name: name}
}

// Project returns the project id.
func (d *Database) Project() string { return d.project }

// Name returns the database name.
func (d *Database) Name() string { return d.name }

func (d *Database) path(extra ...string) ([]string, error) {
	if err := checkID(d.project); err != nil {
		return nil, fmt.Errorf("terrabase: project ID: %w", err)
	}
	if err := checkName("database", d.name); err != nil {
		return nil, err
	}
	return append([]string{"v1", "projects", d.project, "databases", d.name}, extra...), nil
}

// DatabaseInfo is a database as returned by Database.Create.
type DatabaseInfo struct {
	ID        string `json:"id" ulid:"required"`
	ProjectID string `json:"projectId" ulid:"required"`
	Name      string `json:"name"`
	// Created is true when the call created the database (201).
	Created bool `json:"-"`
}

// Create creates the database in its project; an existing database is
// returned unchanged (Created false).
func (d *Database) Create(ctx context.Context) (*DatabaseInfo, error) {
	p, err := d.path()
	if err != nil {
		return nil, err
	}
	var info DatabaseInfo
	resp, err := d.c.call(ctx, request{method: http.MethodPut, path: p, replaySafe: true}, nil, &info)
	if err != nil {
		return nil, err
	}
	info.Created = resp.status == http.StatusCreated
	return &info, nil
}

func (d *Database) CreateCollection(ctx context.Context, name string) (*CollectionInfo, error) {
	if err := checkName("collection", name); err != nil {
		return nil, err
	}
	p, err := d.path("collections")
	if err != nil {
		return nil, err
	}
	var info CollectionInfo
	if _, err := d.c.call(ctx, request{method: http.MethodPost, path: p}, map[string]string{"name": name}, &info); err != nil {
		return nil, err
	}
	return &info, nil
}

func (d *Database) Collection(name string) *Collection { return &Collection{db: d, name: name} }

// Name returns the collection name.
func (col *Collection) Name() string { return col.name }

func (col *Collection) path(extra ...string) ([]string, error) {
	if err := checkName("collection", col.name); err != nil {
		return nil, err
	}
	return col.db.path(append([]string{"collections", col.name}, extra...)...)
}

func (col *Collection) docRequest(method, id string) (request, error) {
	if err := ValidateID(id); err != nil {
		return request{}, fmt.Errorf("terrabase: document ID: %w", err)
	}
	p, err := col.path("documents", "by-key")
	return request{method: method, path: p, query: url.Values{"id": {id}}}, err
}

func (col *Collection) Put(ctx context.Context, id string, doc any, opts ...WriteOption) (*WriteResult, error) {
	req, err := col.docRequest(http.MethodPut, id)
	if err != nil {
		return nil, err
	}
	w, err := resolveWrite(opts)
	if err != nil {
		return nil, err
	}
	body, err := encodeObject(doc)
	if err != nil {
		return nil, err
	}
	req.body, req.header, req.replaySafe = body, w.header(), w.ifMatch != ""
	return col.write(ctx, req)
}

func (col *Collection) write(ctx context.Context, req request) (*WriteResult, error) {
	var res WriteResult
	resp, err := col.db.c.call(ctx, req, nil, &res)
	if err != nil {
		return nil, err
	}
	res.Created = resp.status == http.StatusCreated
	res.Location = resp.header.Get("Location")
	return &res, nil
}

// encodeObject marshals doc and requires a JSON object. json.RawMessage and
// json.Number values pass through unchanged.
func encodeObject(doc any) ([]byte, error) {
	body, err := json.Marshal(doc)
	if err != nil {
		return nil, fmt.Errorf("terrabase: encode document: %w", err)
	}
	if t := bytes.TrimLeft(body, " \t\r\n"); len(t) == 0 || t[0] != '{' {
		return nil, errors.New("terrabase: a document must be a JSON object")
	}
	if err := entityid.Payload(body); err != nil {
		return nil, err
	}
	return body, nil
}
